@Test void householdArchiveListAndDetailUseTheSameDepartmentAndRegionScope()throws Exception{long id=approvedHousehold();executeHousehold(id,200);long archiveId=jdbc.queryForObject("SELECT archive_id FROM household_archive WHERE application_id=?",Long.class,id);authenticate(6L,com.wjx871.population.security.DataScope.DEPARTMENT,4L,"110000");assertThat(cancellationService.archives(null,null,null,null,null,null,org.springframework.data.domain.PageRequest.of(0,10)).getTotalElements()).isEqualTo(1);assertThat(cancellationService.archive(archiveId)).isNotNull();authenticate(2L,com.wjx871.population.security.DataScope.DEPARTMENT,2L,"110000");assertThat(cancellationService.archives(null,null,null,null,null,null,org.springframework.data.domain.PageRequest.of(0,10)).getTotalElements()).isZero();assertThatThrownBy(()->cancellationService.archive(archiveId)).isInstanceOf(com.wjx871.population.common.BusinessException.class);authenticate(9L,com.wjx871.population.security.DataScope.REGION,5L,"110105",List.of("110105","110105001","110105001001"));assertThat(cancellationService.archives(null,null,null,null,null,null,org.springframework.data.domain.PageRequest.of(0,10)).getTotalElements()).isZero();assertThatThrownBy(()->cancellationService.archive(archiveId)).isInstanceOf(com.wjx871.population.common.BusinessException.class);authenticate(10L,com.wjx871.population.security.DataScope.REGION,5L,"110000",List.of("110000","110100","110101","110105","110105001","110105001001"));assertThat(cancellationService.archives(null,null,null,null,null,null,org.springframework.data.domain.PageRequest.of(0,10)).getTotalElements()).isEqualTo(1);assertThat(cancellationService.archive(archiveId)).isNotNull();}
